16: export function resetPassword () {
17:   return async ({ body, connection }: Request, res: Response, next: NextFunction) => {
18:     const email = body.email
19:     const answer = body.answer
20:     const newPassword = body.new
21:     const repeatPassword = body.repeat
22:     if (!email || !answer) {
23:       next(new Error('Blocked illegal activity by ' + connection.remoteAddress))
24:       return
25:     }
26:     if (!newPassword || newPassword === 'undefined') {
27:       res.status(401).send(res.__('Password cannot be empty.'))
28:       return
29:     }
30:     if (newPassword !== repeatPassword) {
31:       res.status(401).send(res.__('New and repeated password do not match.'))
32:       return
33:     }
34:     try {
35:       const data = await SecurityAnswerModel.findOne({
36:         include: [{
37:           model: UserModel,
38:           where: { email }
39:         }]
40:       })
41:       if ((data != null) && security.hmac(answer) === data.answer) {
42:         const user = await UserModel.findByPk(data.UserId)
43:         if (user) {
44:           const updatedUser = await user.update({ password: newPassword })
45:           verifySecurityAnswerChallenges(updatedUser, answer)
46:           res.json({ user: updatedUser })
47:         }
48:       } else {
49:         res.status(401).send(res.__('Wrong answer to security question.'))
50:       }
51:     } catch (error) {
52:       next(error)
53:     }
54:   }
55: }
