57: function verifySecurityAnswerChallenges (user: UserModel, answer: string) {
58:   challengeUtils.solveIf(challenges.resetPasswordJimChallenge, () => { return user.id === users.jim.id && answer === 'Samuel' })
59:   challengeUtils.solveIf(challenges.resetPasswordBenderChallenge, () => { return user.id === users.bender.id && answer === 'Stop\'n\'Drop' })
60:   challengeUtils.solveIf(challenges.resetPasswordBjoernChallenge, () => { return user.id === users.bjoern.id && answer === 'West-2082' })
61:   challengeUtils.solveIf(challenges.resetPasswordMortyChallenge, () => { return user.id === users.morty.id && answer === '5N0wb41L' })
62:   challengeUtils.solveIf(challenges.resetPasswordBjoernOwaspChallenge, () => { return user.id === users.bjoernOwasp.id && answer === 'Zaya' })
63:   challengeUtils.solveIf(challenges.resetPasswordUvoginChallenge, () => { return user.id === users.uvogin.id && answer === 'Silence of the Lambs' })
64:   challengeUtils.solveIf(challenges.geoStalkingMetaChallenge, () => {
65:     const securityAnswer = ((() => {
66:       const memories = config.get<MemoryConfig[]>('memories')
67:       for (let i = 0; i < memories.length; i++) {
68:         if (memories[i].geoStalkingMetaSecurityAnswer) {
69:           return memories[i].geoStalkingMetaSecurityAnswer
70:         }
71:       }
72:     })())
73:     return user.id === users.john.id && answer === securityAnswer
74:   })
75:   challengeUtils.solveIf(challenges.geoStalkingVisualChallenge, () => {
76:     const securityAnswer = ((() => {
77:       const memories = config.get<MemoryConfig[]>('memories')
78:       for (let i = 0; i < memories.length; i++) {
79:         if (memories[i].geoStalkingVisualSecurityAnswer) {
80:           return memories[i].geoStalkingVisualSecurityAnswer
81:         }
82:       }
83:     })())
84:     return user.id === users.emma.id && answer === securityAnswer
85:   })
86: }

